# Break My Fix finding 1, generated by Tracefix: unyt_array.to_astropy returns a wrong value.
# Property (docstring): For dimensionless units, including scaled ones like cm/m, the astropy quantity must have the same pure-number value once its units are cancelled out.
# Quote: Creates a new AstroPy quantity with the same unit information.
# Run it with pytest: it fails for as long as the code breaks this property.

import copy
import math

from unyt.array import unyt_array, unyt_quantity


def test_break_my_fix_1() -> None:
    self_after = unyt_quantity(5.0, 'km/m')
    self = copy.deepcopy(self_after)
    # The property applies to this input: self.units.is_dimensionless
    result = self_after.to_astropy()
    assert (len(list(result.decompose().value.flat)) == len(list(self.to('dimensionless').value.flat)) and all(math.isclose(float(a), float(b), rel_tol=1e-9, abs_tol=1e-300) for a, b in zip(list(result.decompose().value.flat), list(self.to('dimensionless').value.flat))))
